<script setup lang="ts">
import type{components}from'~/api/schema';import{unwrap,versionHeaders}from'~/api/client';import{displayError}from'~/utils/errors';import{formatDate,formatRupiah,statusLabel}from'~/utils/format';type Refund=components['schemas']['Refund'];definePageMeta({middleware:['auth','admin']});const api=useMarketplaceApi();const appAlert=useAppAlert();const refunds=ref<Refund[]>([]);const selected=ref<Refund>();const operationId=ref('');const pending=ref(true);const message=ref('');const form=reactive({payment_receipt_id:'',reason:'',vendor_order_id:'',order_item_id:'',component:'ITEM' as 'ITEM'|'SHIPPING'|'BUYER_FEE'|'EXCESS_PAYMENT',amount:0});const result=reactive({state:'SUCCEEDED' as 'SUCCEEDED'|'FAILED'|'UNKNOWN',proof_document_id:'',external_reference:'',reason:''})
async function load(){pending.value=true;try{refunds.value=unwrap(await api.GET('/admin/refunds',{params:{query:{limit:100}},cache:'no-store'})).items;if(selected.value)selected.value=refunds.value.find(x=>x.id===selected.value?.id)}catch(cause){message.value=displayError(cause).message}finally{pending.value=false}}
async function create(){try{selected.value=unwrap(await api.POST('/admin/refunds',{params:{header:{'Idempotency-Key':crypto.randomUUID()}},body:{payment_receipt_id:form.payment_receipt_id,reason:form.reason,lines:[{vendor_order_id:form.vendor_order_id||undefined,order_item_id:form.order_item_id||undefined,component:form.component,amount:form.amount}]}}));await load()}catch(cause){message.value=displayError(cause).message}}
async function approve(){if(!selected.value)return;const reason=await appAlert.promptText({title:'Setujui refund?',text:'Tindakan ini akan memulai proses pengembalian dana.',inputLabel:'Alasan persetujuan',confirmText:'Setujui refund'});if(!reason)return;try{const op=unwrap(await api.POST('/admin/refunds/{refundId}/approve',{params:{path:{refundId:selected.value.id},header:{...versionHeaders(selected.value.row_version),'Idempotency-Key':crypto.randomUUID()}},body:{reason}}));operationId.value=op.id;await appAlert.success({title:'Refund disetujui',text:'Proses refund telah masuk ke antrean.'})}catch(cause){message.value=displayError(cause).message;await appAlert.error({title:'Refund gagal disetujui',text:message.value})}}
async function record(){if(!selected.value)return;try{selected.value=unwrap(await api.POST('/admin/refunds/{refundId}/manual-result',{params:{path:{refundId:selected.value.id},header:{...versionHeaders(selected.value.row_version),'Idempotency-Key':crypto.randomUUID()}},body:{state:result.state,proof_document_id:result.proof_document_id||undefined,external_reference:result.external_reference||undefined,reason:result.reason}}));await load()}catch(cause){message.value=displayError(cause).message}}
onMounted(()=>{void load()});useSeoMeta({title:'Refund admin — Niaga'})
</script>
<template><main id="main-content" class="page-shell"><PortalNav area="admin"/><div class="section-heading"><div><p class="eyebrow">Maker / approver</p><h1>Refund</h1></div></div><p v-if="message" class="surface" role="status">{{message}}</p><div class="admin-split"><section><ApiState :pending="pending" :empty="!pending&&!refunds.length" empty-title="Belum ada refund"><div class="card-list"><button v-for="item in refunds" :key="item.id" class="surface selection-card" @click="selected=item"><span>{{formatDate(item.created_at)}}</span><strong>{{formatRupiah(item.amount)}}</strong><span class="badge">{{statusLabel(item.state)}}</span><small>{{item.reason}}</small></button></div></ApiState></section><form class="surface form-stack" @submit.prevent="create"><h2>Permintaan refund</h2><label class="form-field">Payment receipt ID<input v-model="form.payment_receipt_id" required></label><label class="form-field">Vendor order ID<input v-model="form.vendor_order_id"></label><label class="form-field">Order item ID<input v-model="form.order_item_id"></label><label class="form-field">Komponen<select v-model="form.component"><option>ITEM</option><option>SHIPPING</option><option>BUYER_FEE</option><option>EXCESS_PAYMENT</option></select></label><label class="form-field">Nominal<input v-model.number="form.amount" type="number" min="1" required></label><label class="form-field">Alasan<textarea v-model="form.reason" minlength="3" required/></label><button>Buat refund</button></form></div><section v-if="selected" class="surface section"><div class="section-heading"><div><h2>Refund {{selected.id.slice(0,8)}}</h2><p>{{formatRupiah(selected.amount)}} · {{selected.reason}}</p></div><span class="badge">{{statusLabel(selected.state)}}</span></div><div class="form-actions"><button v-if="selected.state==='REQUESTED'" @click="approve">Setujui sebagai approver</button></div><OperationStatus v-if="operationId" :operation-id="operationId" @complete="load"/><form v-if="['PROCESSING','UNKNOWN'].includes(selected.state)" class="form-stack section" @submit.prevent="record"><h3>Catat hasil manual</h3><label class="form-field">Hasil<select v-model="result.state"><option>SUCCEEDED</option><option>FAILED</option><option>UNKNOWN</option></select></label><label class="form-field">Referensi eksternal<input v-model="result.external_reference"></label><label class="form-field">Proof document ID<input v-model="result.proof_document_id"></label><label class="form-field">Alasan<input v-model="result.reason" minlength="3" required></label><button>Catat hasil</button></form></section></main></template>
